#!/bin/bash
# Uninstall script for Nextcloud Talk Desktop
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling Nextcloud Talk Desktop..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping Nextcloud Talk Desktop if running..."
pkill -f "Nextcloud Talk Desktop" 2>/dev/null || true

# Remove /Applications/Nextcloud Talk.app
echo "Removing /Applications/Nextcloud Talk.app..."
if [ -d "/Applications/Nextcloud Talk.app" ]; then
    rm -rf "/Applications/Nextcloud Talk.app" 2>/dev/null || true
elif [ -f "/Applications/Nextcloud Talk.app" ]; then
    rm -f "/Applications/Nextcloud Talk.app" 2>/dev/null || true
fi

# Remove $HOME/Library/Application Support/Nextcloud Talk
echo "Removing $HOME/Library/Application Support/Nextcloud Talk..."
if [ -d "$HOME/Library/Application Support/Nextcloud Talk" ]; then
    rm -rf "$HOME/Library/Application Support/Nextcloud Talk" 2>/dev/null || true
elif [ -f "$HOME/Library/Application Support/Nextcloud Talk" ]; then
    rm -f "$HOME/Library/Application Support/Nextcloud Talk" 2>/dev/null || true
fi

# Remove $HOME/Library/Preferences/com.nextcloud.talk.mac.plist
echo "Removing $HOME/Library/Preferences/com.nextcloud.talk.mac.plist..."
if [ -d "$HOME/Library/Preferences/com.nextcloud.talk.mac.plist" ]; then
    rm -rf "$HOME/Library/Preferences/com.nextcloud.talk.mac.plist" 2>/dev/null || true
elif [ -f "$HOME/Library/Preferences/com.nextcloud.talk.mac.plist" ]; then
    rm -f "$HOME/Library/Preferences/com.nextcloud.talk.mac.plist" 2>/dev/null || true
fi

echo "Uninstallation complete!"
exit 0
